def history_embedding(self, seq: torch.Tensor) -> torch.Tensor:
    frequency = self.frequency_projection(self.frequency_emb(self.frequency_bins[seq]))
    frequency = frequency.masked_fill(seq.eq(0).unsqueeze(-1), 0.0)
    return self.dropout(self.item_emb(seq) + frequency)

